class Solution:
    def maximizeSweetness(self, sweetness: List[int], k: int) -> int:
        total = sum(sweetness)
        left, right = 0, total // (k + 1)

        def can_make(target: int) -> bool:
            pieces = 0
            current = 0
            for value in sweetness:
                current += value
                if current >= target:
                    pieces += 1
                    current = 0
            return pieces >= k + 1

        while left < right:
            mid = (left + right + 1) // 2
            if can_make(mid):
                left = mid
            else:
                right = mid - 1

        return left

