#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int maximizeSweetness(const int sweetness[], int n, int k) {
    long long total = 0;
    for (int i = 0; i < n; ++i) {
        total += sweetness[i];
    }

    int left = 0;
    int right = (int)(total / (k + 1));

    while (left < right) {
        int mid = left + (right - left + 1) / 2;

        int pieces = 0;
        int current = 0;
        for (int i = 0; i < n; ++i) {
            current += sweetness[i];
            if (current >= mid) {
                ++pieces;
                current = 0;
            }
        }

        if (pieces >= k + 1) {
            left = mid;
        } else {
            right = mid - 1;
        }
    }

    return left;
}

