#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    int maximizeSweetness(vector<int>& sweetness, int k) {
        long long total = accumulate(sweetness.begin(), sweetness.end(), 0LL);
        int left = 0;
        int right = static_cast<int>(total / (k + 1));

        while (left < right) {
            int mid = left + (right - left + 1) / 2;
            if (canMake(sweetness, k, mid)) {
                left = mid;
            } else {
                right = mid - 1;
            }
        }
        return left;
    }

private:
    bool canMake(const vector<int>& sweetness, int k, int target) {
        int pieces = 0;
        int current = 0;

        for (int value : sweetness) {
            current += value;
            if (current >= target) {
                ++pieces;
                current = 0;
            }
        }
        return pieces >= k + 1;
    }
};

int main() {
    string line;
    getline(cin, line);

    size_t firstClose = line.find(']', 1);
    string arrayText = line.substr(2, firstClose - 2);
    string kText = line.substr(firstClose + 2, line.size() - firstClose - 3);

    vector<int> sweetness;
    if (!arrayText.empty()) {
        stringstream ss(arrayText);
        string token;
        while (getline(ss, token, ',')) {
            sweetness.push_back(stoi(token));
        }
    }

    int k = stoi(kText);
    int result = Solution().maximizeSweetness(sweetness, k);
    cout << result << '\n';
    return 0;
}

