import java.io.*;
import java.util.*;

class Solution {
    public int maximizeSweetness(int[] sweetness, int k) {
        int left = 0;
        long total = 0;
        for (int value : sweetness) {
            total += value;
        }
        int right = (int)(total / (k + 1));

        while (left < right) {
            int mid = left + (right - left + 1) / 2;
            if (canMake(sweetness, k, mid)) {
                left = mid;
            } else {
                right = mid - 1;
            }
        }
        return left;
    }

    private boolean canMake(int[] sweetness, int k, int target) {
        int pieces = 0;
        int current = 0;
        for (int value : sweetness) {
            current += value;
            if (current >= target) {
                pieces++;
                current = 0;
            }
        }
        return pieces >= k + 1;
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine().trim();

        int firstClose = line.indexOf(']', 1);
        String arrayText = line.substring(2, firstClose);
        String kText = line.substring(firstClose + 2, line.length() - 1).trim();

        String[] parts = arrayText.isEmpty() ? new String[0] : arrayText.split(",");
        int[] sweetness = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            sweetness[i] = Integer.parseInt(parts[i].trim());
        }

        int k = Integer.parseInt(kText);
        int result = new Solution().maximizeSweetness(sweetness, k);
        System.out.println(result);
    }
}

